package com.bank.approval.service;

import java.util.logging.Logger;

// Counts ways to reach the final stage taking 1, 2, or 3 stages per action.
public class ApprovalPathService {
    private static final Logger log = Logger.getLogger(ApprovalPathService.class.getName());

    public long countWays(int stages) {
        if (stages == 0) return 1;
        if (stages == 1) return 1;
        if (stages == 2) return 2;
        long a = 1, b = 1, c = 2;                   // ways to reach 0, 1, 2
        for (int i = 3; i <= stages; i++) {
            long cur = a + b + c;                   // sum of previous three
            a = b; b = c; c = cur;                  // slide the window
        }
        final long r = c;
        log.info(() -> "Ways to reach stage " + stages + " = " + r);
        return c;
    }
}
